import{_ as o,C as i,c as n,o as t,a2 as s,b as l,w as a,a as d,G as p,a3 as c}from"./chunks/framework.DkPtUiZm.js";const u="/sia-ui-site/assets/apercu-carrousel-v2.D3utwoic.png",m="/sia-ui-site/assets/apercu-captures.Ci1LcK_j.png",P=JSON.parse('{"title":"Visuels Google Play de SIA UI Demo","description":"","frontmatter":{},"headers":[],"relativePath":"guides/visuels-google-play.md","filePath":"guides/visuels-google-play.md","lastUpdated":1795438092000}'),h={name:"guides/visuels-google-play.md"};function g(f,e,v,b,C,A){const r=i("Mermaid");return t(),n("div",null,[e[1]||(e[1]=s('<h1 id="visuels-google-play-de-sia-ui-demo" tabindex="-1">Visuels Google Play de SIA UI Demo <a class="header-anchor" href="#visuels-google-play-de-sia-ui-demo" aria-label="Permalink to &quot;Visuels Google Play de SIA UI Demo&quot;">​</a></h1><p>Le lot français pour la fiche Android téléphone se trouve dans <a href="./../assets/google-play/README.html"><code>docs/assets/google-play/</code></a>. Le carrousel principal comporte huit compositions avec téléphones en volume, textes en français et continuité par paires. Il utilise comme références les captures de l&#39;application <strong>1.0.0, versionCode 1</strong>, installée sur un téléphone Android 17. Les six écrans sont aussi disponibles en captures simples, en mode clair et sombre.</p><h2 id="fichiers-a-importer" tabindex="-1">Fichiers à importer <a class="header-anchor" href="#fichiers-a-importer" aria-label="Permalink to &quot;Fichiers à importer&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Champ Play Console</th><th>Fichier ou dossier</th><th>Format</th></tr></thead><tbody><tr><td>Icône de l&#39;application</td><td><a href="../assets/google-play/icone-512.png">icone-512.png</a></td><td>512 × 512, PNG RGBA opaque</td></tr><tr><td>Image de présentation, version sombre</td><td><a href="../assets/google-play/fr-FR/image-presentation-1024x500.png">image-presentation-1024x500.png</a></td><td>1024 × 500, PNG RGB</td></tr><tr><td>Image de présentation, variante claire</td><td><a href="../assets/google-play/fr-FR/image-presentation-claire-1024x500.png">image-presentation-claire-1024x500.png</a></td><td>1024 × 500, PNG RGB</td></tr><tr><td>Visuels téléphone, carrousel recommandé</td><td><code>fr-FR/carrousel-v2/</code>, dans le lot</td><td>8 PNG RGB, 1080 × 1920</td></tr><tr><td>Captures simples, sélection alternative</td><td><code>fr-FR/selection-8/</code>, dans le lot</td><td>8 PNG RGB, 1080 × 1920</td></tr><tr><td>Captures téléphone, série claire</td><td><code>fr-FR/telephone/clair/</code>, dans le lot</td><td>6 PNG RGB, 1080 × 1920</td></tr><tr><td>Captures téléphone, série sombre</td><td><code>fr-FR/telephone/sombre/</code>, dans le lot</td><td>6 PNG RGB, 1080 × 1920</td></tr></tbody></table><p>L&#39;icône et <strong>une seule</strong> des deux images de présentation remplissent les champs correspondants. Pour les captures, utiliser les huit fichiers numérotés du carrousel, ou composer une sélection de huit images au maximum parmi les deux séries. Les douze variantes ne doivent pas être envoyées dans le même emplacement téléphone. Les dimensions et formats suivent les <a href="https://support.google.com/googleplay/android-developer/answer/9866151?hl=fr" target="_blank" rel="noreferrer">consignes Google Play</a>.</p><p>Le <a href="../assets/google-play/sia-ui-demo-google-play.zip">ZIP du lot</a> regroupe les exports, les sources et les textes alternatifs.</p><h2 id="carrousel-avec-telephones" tabindex="-1">Carrousel avec téléphones <a class="header-anchor" href="#carrousel-avec-telephones" aria-label="Permalink to &quot;Carrousel avec téléphones&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Ordre d&#39;import</th><th>Sujet</th><th>Accroches</th></tr></thead><tbody><tr><td>01–02</td><td>Catalogue, clair et sombre</td><td>Tous les composants. / Clair ou sombre. Toujours cohérent.</td></tr><tr><td>03–04</td><td>Formulaire et clavier</td><td>Des formulaires bien structurés. / Une saisie qui reste fluide.</td></tr><tr><td>05–06</td><td>Feuille et calendrier</td><td>Feuilles souples. Gestes naturels. / Les dates, sans détour.</td></tr><tr><td>07–08</td><td>Contacts, clair et sombre</td><td>Des contacts. Un vrai parcours. / Local, simple et interactif.</td></tr></tbody></table><p><img src="'+u+'" alt="Aperçu du carrousel avec téléphones"></p><p>Chaque paire provient d&#39;un panorama unique, découpé sans espace intermédiaire : le téléphone et les rubans se poursuivent entre 01–02, 03–04, 05–06 et 07–08. La continuité s&#39;applique à l&#39;intérieur de ces paires. La <a href="../assets/google-play/frise-carrousel-v2.png">frise des huit visuels</a> permet d&#39;en vérifier l&#39;ordre.</p><p>Ces compositions marketing ont été générées avec l&#39;outil <strong>imagegen intégré</strong>, en prenant les captures Android comme références. Les écrans insérés peuvent présenter des différences de détail liées à la génération ; ils ne sont pas des copies pixel à pixel des captures. Les captures simples ci-dessous conservent le rendu applicatif réel. Les <a href="./../assets/google-play/sources/carrousel-v2/prompts.html">prompts complets</a>, les originaux générés et les panoramas normalisés sont conservés dans les sources.</p><h2 id="captures-simples-alternatives" tabindex="-1">Captures simples alternatives <a class="header-anchor" href="#captures-simples-alternatives" aria-label="Permalink to &quot;Captures simples alternatives&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Numéro dans chaque série</th><th>Écran</th><th>Contenu visible</th></tr></thead><tbody><tr><td>01</td><td>Catalogue</td><td>Recherche, familles et variantes de boutons</td></tr><tr><td>02</td><td>Formulaire</td><td>Sections, labels et champs de saisie</td></tr><tr><td>03</td><td>Clavier</td><td>Saisie du nom fictif Alex Martin, clavier Android ouvert</td></tr><tr><td>04</td><td>BottomSheet</td><td>Feuille ouverte, poignée, positions, recherche et ressources</td></tr><tr><td>05</td><td>Calendrier</td><td>Novembre 2026, date sélectionnée et réservation locale</td></tr><tr><td>06</td><td>Contacts</td><td>Contacts fictifs, adresses <code>example.test</code>, statuts et actions</td></tr></tbody></table><p><img src="'+m+'" alt="Aperçu des douze captures en modes clair et sombre"></p><p>Les textes alternatifs, limités à 140 caractères, sont fournis dans <a href="./../assets/google-play/textes-alternatifs.html"><code>textes-alternatifs.md</code></a> et dans <a href="../assets/google-play/manifest.json"><code>manifest.json</code></a>.</p><h2 id="provenance-et-mise-a-jour" tabindex="-1">Provenance et mise à jour <a class="header-anchor" href="#provenance-et-mise-a-jour" aria-label="Permalink to &quot;Provenance et mise à jour&quot;">​</a></h2>',16)),(t(),l(c,null,{default:a(()=>[p(r,{id:"mermaid-277",class:"mermaid",graph:"flowchart%20LR%0A%20%20Logo%5B%22Logo%20vectoriel%20SIA%20existant%22%5D%20--%3E%20Marque%5B%22Ic%C3%B4ne%20et%20deux%20banni%C3%A8res%22%5D%0A%20%20APK%5B%22APK%20EAS%20preview%201.0.0%22%5D%20--%3E%20App%5B%22Application%20Android%20sur%20t%C3%A9l%C3%A9phone%22%5D%0A%20%20App%20--%3E%20Capture%5B%22Six%20%C3%A9crans%20%C3%97%20deux%20th%C3%A8mes%22%5D%0A%20%20Capture%20--%3E%20Cadrage%5B%22Retrait%20des%20barres%20syst%C3%A8me%3Cbr%2F%3Emise%20%C3%A0%20l'%C3%A9chelle%20proportionnelle%22%5D%0A%20%20Cadrage%20--%3E%20PNG%5B%22Captures%20simples%201080%20%C3%97%201920%22%5D%0A%20%20Capture%20--%3E%20Imagegen%5B%22imagegen%20%3A%20quatre%20panoramas%20avec%20t%C3%A9l%C3%A9phones%22%5D%0A%20%20Imagegen%20--%3E%20Decoupe%5B%22Normalisation%202160%20%C3%97%201920%3Cbr%2F%3Ed%C3%A9coupe%20en%20huit%20PNG%201080%20%C3%97%201920%22%5D%0A%20%20Marque%20--%3E%20Verification%5B%22Contr%C3%B4le%20visuel%2C%20dimensions%20et%20formats%22%5D%0A%20%20PNG%20--%3E%20Verification%0A%20%20Decoupe%20--%3E%20Verification%0A%20%20Verification%20--%3E%20Lot%5B%22S%C3%A9lection%20de%20huit%2C%20s%C3%A9ries%2C%20sources%20et%20ZIP%22%5D%0A%20%20Lot%20--%3E%20Console%5B%22Import%20manuel%20dans%20Play%20Console%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=s('<p>Le build EAS utilisé est <code>9fa54e15-4268-4390-8cdc-c3d2f27a5573</code>, profil <code>preview</code>. L&#39;empreinte SHA-256 de l&#39;APK installé correspond à celle de l&#39;archive de ce build :</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>a0200890ccf43a74444d87ce9b9d6114be533fe83bae908c3c69847e22f468f3</span></span></code></pre></div><p>Les prises de vue originales mesurent 1080 × 2340. Le cadrage retire uniquement 112 pixels en haut et 76 pixels en bas, correspondant aux barres système et à leur marge ; il conserve l&#39;interface, les champs, les données et les couleurs. L&#39;interface est réduite proportionnellement et placée dans une composition 1080 × 1920 avec un titre court et l&#39;indication du thème. Dans ces séries simples, aucun écran applicatif n&#39;a été redessiné ou généré par IA. Le clavier visible appartient au téléphone.</p><p>Les captures applicatives recadrées sont conservées dans <code>sources/captures/</code>. Les compositions SVG éditables utilisent ces PNG par chemins relatifs. Les sources de l&#39;icône et des deux bannières restent vectorielles, dérivées du signe officiel <code>docs/assets/sia-ui-mark.svg</code>.</p><p>Les quatre originaux imagegen de 1330 × 1182 sont normalisés proportionnellement en 2160 × 1920, puis coupés à x = 1080. Le réassemblage des deux exports a été comparé aux pixels du panorama normalisé : les quatre raccords sont exacts. Les compositions marketing sont livrées comme PNG ; les sources SVG éditables concernent les captures simples, l&#39;icône et les bannières.</p><p>Les PNG ont été ouverts et contrôlés, leurs dimensions et canaux vérifiés, et les variantes simples comparées aux séries sources. Toute modification visible dans l&#39;APK destiné à la publication demande une nouvelle prise de vue des écrans concernés, puis une mise à jour du manifeste, du ZIP et de l&#39;aperçu.</p><p><strong>Prévu :</strong> captures spécifiques à une tablette si sa fiche est préparée. Les captures téléphone ne doivent pas être présentées comme des captures tablette. La vidéo promotionnelle n&#39;est pas incluse dans ce lot d&#39;images.</p>',7))])}const _=o(h,[["render",g]]);export{P as __pageData,_ as default};
